N = int(input())
beans = [list(map(int, input().split())) for _ in range(N)]

# Dictionary to store the minimum deliciousness value for each color
color_min = {}

for deliciousness, color in beans:
    if color in color_min:
        color_min[color] = min(color_min[color], deliciousness)
    else:
        color_min[color] = deliciousness

# Find the maximum of the minimum deliciousness values for each color
max_min_deliciousness = max(color_min.values())

print(max_min_deliciousness)
